    "abstractSummaryId": "Crisis requires society to renew itself, albeit in a disruptive way. The current Covid-19 pandemic is transforming ways of working, living, and relating to each other on a global level, suddenly and dramatically. This paper focuses on the field of education to show how higher education institutions are undergoing radical transformations driven by the need to digitalize education and training processes in record time with academics who lack innate technological capabilities for online teaching. The university system must strive to overcome this situation to be competitive and provide high-quality education in a...",
    "methodology": "Penelitian Empiris Psikologi (Lihat detail desain pada artikel sumber)",
    "sampleContext": "Detail jumlah & karakteristik partisipan tercantum lengkap pada teks penuh artikel DOI",
    "keyFindings": [
      "The university system must strive to overcome this situation to be competitive and provide high-quality education in a scenario of digital transformation, disruptive technological innovations, and accelerated change.",
      "To achieve these goals, this paper explains some barriers and challenges that universities encounter, as well as technological resources and methodologies they have used in the current scenario to transform higher education to face Covid-19 disruption.",
      "The discussion and conclusion synthesize significant insights that can be applied to the digitalization of education in the foreseeable future."
    ],
