    "abstractSummaryId": "As an important predictor of academic achievement and an effective indicator of learning quality, academic engagement has attracted the attention of researchers. The present study explores the relationship among adolescent self-esteem and academic engagement, the mediating effect of academic self-efficacy, and the moderating effect of perceived social support. Four-hundred and eighty adolescents ( M age = 14.92) from the Hebei Province of China were recruited to complete anonymous questionnaires. The results show that self-esteem positively predicted adolescent academic engagement through the indirect mediatin...",
