    "abstractSummaryId": "Objective: This study aims to investigate the relationship and mechanisms of action among academic stress, academic anxiety, academic self-efficacy, and academic burnout among adolescents. Methods: A study of 929 Chinese adolescents (53.71% males, mean age = 11.94 years, SD = 0.77) was conducted using the Study Stress Questionnaire, Academic Anxiety Subscale, Junior Middle School Students' Learning Weariness Scale, and the Academic Self-efficacy Questionnaire. Results: ①Academic stress was significantly and positively correlated with academic anxiety and academic burnout, and significantly and negatively corre...",
