    "sampleContext": "Detail jumlah & karakteristik partisipan tercantum lengkap pada teks penuh artikel DOI",
    "keyFindings": [
      "③Academic self-efficacy significantly moderated the direct effect of academic stress on academic burnout, and higher academic self-efficacy could buffer the negative effect of academic stress.",
      "④Academic self-efficacy significantly moderated the second half of the mediated model's path (academic anxiety → academic burnout), that is, low academic self-efficacy amplified the risk effect of academic anxiety on academic burnout.",
      "Conclusion: Academic anxiety partially mediates the relationship between academic stress and academic burnout, and this mediating role is moderated by academic self-efficacy."
    ],
