    "abstractSummaryId": "Artificial intelligence (AI) technology has been widely applied in many fields. AI-assisted learning environments have been implemented in classrooms to facilitate the innovation of pedagogical models. However, college students' willingness to accept (WTA) AI-assisted learning environments has been ignored. Exploring the factors that influence college students' willingness to use AI can promote AI technology application in higher education. Based on the Unified Theory of Acceptance and Use of Technology (UTAUT) and the theory of perceived risk, this study identified six factors that influence students' willing...",
