    "abstractSummaryId": "The COVID-19 pandemic has had a significant impact on education worldwide. The disease first hit China and numerous Chinese cities then started to conduct online courses. Therefore, this study aims to explore the effect of the Shanghai students' emotional intelligence, learning motivation, and self-efficacy on their academic achievement when they participated in online English classes during the latter phase of the pandemic in China. Furthermore, the research also examines whether the students' emotional intelligence can influence their academic achievement through the mediation effect of their learning motiva...",
