    "abstractSummaryId": "Introduction: One of the biggest challenges facing students today is procrastination, which is closely related to stress, anxiety and, in the most severe cases, depression. The aim of the present study is to analyze the influence of academic self-regulation on procrastination, academic anxiety and stress, academic resilience and academic performance. Method: = 17.25; SD = 3.45). A structural equation model was used to analyze the relationship between the study variables. Results: Analyzes showed that academic self-regulation negatively predicted procrastination. In turn, procrastination positively predicted ac...",
