    "abstractSummaryId": "The global coronavirus disease 2019 (COVID-19) pandemic has caused significant uncertainty for students and teachers. During this time, teacher and student creative beliefs and affect play a supportive role in adaptively managing stress, finding joy, and bouncing back from inevitable setbacks with resilience. Developing an adaptive orientation to creativity is a critically important step in helping teachers deal with the challenges and stress of reaching their students through distance learning, especially the most marginalized. This study aims to understand how teacher creativity linked to well-being in the f...",
