    "abstractSummaryId": "OBJECTIVE AND BACKGROUND: Academic procrastination as deliberate postponement of academic tasks, despite being aware of its consequences, is a common phenomenon among students. Current conceptualizations of procrastination support the rule of emotion regulation difficulties in the psychopathology of this phenomenon. In this regard, the current study is aimed to investigate the role of difficulty in emotion regulation in academic procrastination. METHOD: The present study is a cross-sectional study. Participants were 250 students who completed Tuckman Procrastination Scale (TPS), and Difficulties in Emotion Reg...",
