    "abstractSummaryId": "In addition to attempting to verify gender differences, this study aims to examine the explanatory potential of boys’ and girls’ attitudes towards mathematics on their performance. The sample comprised 897 students in the 5th and 6th years of primary education (450 boys, 447 girls). The results confirm what previous research has suggested, girls tended to exhibit less positive attitudes about mathematics than their male classmates, in particular lower motivation, worse perception of competence and higher rates of anxiety, although in all cases the effect sizes were small. Even though there no significant gende...",
