    "abstractSummaryId": "Reflective journal (RJ) writing has been recognized as an effective pedagogical tool for nurturing students' lifelong learning skills. With the paucity of empirical work on the dimensionality of reflective writing, this research sought to qualitatively analyze students' RJ writing and design a generic reflection scheme for identifying dimensions of reflective thinking. Drawing on the theoretical scheme, another aim was to design and validate a questionnaire to measure students' perceptions of their reflective writing experiences. The last aim was to quantitatively measure the link between perceived reflective...",
