    "abstractSummaryId": "As traditional handwriting is progressively being replaced by digital devices, it is essential to investigate the implications for the human brain. Brain electrical activity was recorded in 36 university students as they were handwriting visually presented words using a digital pen and typewriting the words on a keyboard. Connectivity analyses were performed on EEG data recorded with a 256-channel sensor array. When writing by hand, brain connectivity patterns were far more elaborate than when typewriting on a keyboard, as shown by widespread theta/alpha connectivity coherence patterns between network hubs and...",
