    "abstractSummaryId": "The rapid and unplanned change to teaching and learning in the online format brought by COVID-19 has likely impacted many, if not all, aspects of university students' lives worldwide. To contribute to the investigation of this change, this study focuses on the impact of the pandemic on student well-being, which has been found to be as important to student lifelong success as their academic achievement. Student well-being has been linked to their engagement and performance in curricular, co-curricular, and extracurricular activities, intrinsic motivation, satisfaction, meaning making, and mental health. The pur...",
    "methodology": "Survei Kuantitatif (Pemodelan Struktural / Regresi)",
    "sampleContext": "Detail jumlah & karakteristik partisipan tercantum lengkap pada teks penuh artikel DOI",
    "keyFindings": [
      "In turn, concerns for future job prospects affect student well-being over time.",
      "These results suggest that in a \"new normal,\" universities could increase student well-being by making support to student studies a priority, especially for undergraduates.",
      "Also, universities should be aware of the students' changing emotional responses to crisis and ensure visibility and accessibility of student support."
    ],
