    "abstractSummaryId": "Studies in recent years have shown that academic procrastination in postgraduates is very common and has a negative impact on their mental health. Therefore, we conducted this study to explore the influencing mechanism of postgraduate academic procrastination. In this study, based on the Temporal Decision Model (TDM) of procrastination and the strength model of self-control, we administered a questionnaire survey to 577 full-time postgraduates (351 females, 226 males) to explore the influence mechanisms and gender differences of motivational and volitional factors on academic procrastination. Our results indic...",
