    "abstractSummaryId": "Introduction This study investigated the role of generative Artificial Intelligence (AI) in enhancing the creative cognition of design students, examining the mediating effects of self-efficacy and anxiety reduction. Methods A quantitative approach was employed, collecting data through online surveys from 121 design students at universities in southern China. The study utilized scales for AI knowledge and perception, self-efficacy, anxiety, and creative cognition, adapted from previous studies and evaluated on 5-point Likert scales. Data analysis was conducted using SPSS 24.0 for exploratory factor analysis an...",
