    "abstractSummaryId": "In response to the Covid-19 pandemic, online learning has been carried out in many countries with different types of online learning models being promoted and implemented. In the global pandemic continues, the education environment is forced to change from traditional classroom or blended teaching mode to online learning teaching model. With the outbreak of COVID-19, China was the first to announce that online courses are to be implemented in February 2020. In China, whether online learning can replace traditional offline teaching has become a topic worth discussing. Therefore, this study investigates universi...",
