    "abstractSummaryId": "The COVID-19 pandemic brought rapid changes to travel, learning environments, work conditions, and social support, which caused stress for many University students. Research with young people has revealed music listening to be among their most effective strategies for coping with stress. As such, this survey of 402 first-year Australian University students (73.9% female, Mage = 19.6; 75% domestic and 25% international) examined the effectiveness of music listening during COVID-19 compared with other stress management strategies, whether music listening for stress management was related to well-being, and wheth...",
