    "abstractSummaryId": "Quality interventions addressing the important issue of teacher stress and burnout have shown promising outcomes for participating teachers in terms of decreased distress, improved well-being and increased commitment to their jobs. Less is known however about whether such interventions also benefit students. The present study investigated the downstream effects for a completer sample of 226 primary and high school students after their teachers (n = 17) completed one of two 8-week stress reduction interventions. The relationships between change in teacher self-reported distress and burnout after completing the...",
