    "abstractSummaryId": "The COVID-19 pandemic at the beginning of 2020 has changed the conventional learning mode for most students at schools all over the world, and the e-learning at home has become a new trend. Taking Chinese college students as the research subject and drawing on the stimulus-organism-response (S-O-R) model, this paper examines the relationship between the peer referent, perceived closeness, and perceived control and the learning engagement. Using data from 377 college students who have used e-learning, this study shows that perceived closeness, perceived control, and peer referents in e-learning have a positive...",
