    "keyFindings": [
      "Taking Chinese college students as the research subject and drawing on the stimulus-organism-response (S-O-R) model, this paper examines the relationship between the peer referent, perceived closeness, and perceived control and the learning engagement.",
      "Using data from 377 college students who have used e-learning, this study shows that perceived closeness, perceived control, and peer referents in e-learning have a positive effect on the self-efficacy and well-being of students, thus improving students' en...",
      "Our intent is to assist researchers, instructors, designers, and others in identifying effective methods to conceptualize and measure student engagement in e-learning."
    ],
