    "abstractSummaryId": "As a relatively new dimension of student engagement, agentic engagement has received growing research interest in recent years, as it not only predicts academic achievement and other positive outcomes, but also benefits reciprocal teacher-student relations. In the educational context, teachers' teaching style exerts a crucial impact on students' engagement. However, research on how perceived teachers' teaching style influences students' agentic engagement is inconclusive. To address this lacuna, this study, taking an integrated perspective that draws on Self-determination Theory and Achievement Goal Theory, in...",
