    "abstractSummaryId": "The problem of mobile phone addiction and academic procrastination among medical students has been widely acknowledged. This study aimed to explore the influence of demographic factors on mobile phone addiction, academic procrastination, and academic achievement among medical students. Further, it investigated the association between mobile phone addiction, academic procrastination, and academic achievement. This cross-sectional study was conducted between May and June 2019. A total of 3 511 medical students participated in an online questionnaire survey (effective response rate = 81.7%). Demographic factors,...",
