    "abstractSummaryId": "With the advent of positive psychology in second language (L2) learning, some researchers have undertaken empirical studies to explore emotional variables affecting L2 learning and how positive emotions can enhance the engagement of L2 learners. As an attempt to contribute to this research domain, this project sought to test a model of student engagement based on classroom social climate (CSC) and foreign language enjoyment (FLE) among English language learners in Iran. A sample of 386 intermediate English as a foreign language (EFL) learners took part in this survey by completing the online battery of questio...",
