    "abstractSummaryId": "Entrepreneurship in higher education is increasingly valuing entrepreneurial creativity as a significant driver for improving university students' innovative abilities. The purpose of this study was to examine the direct influence of entrepreneurial education and creativity on entrepreneurial intention, as well as the indirect role of entrepreneurial inspiration, mindset, and self-efficiency. This study gathered survey responses from 448 university business students from three Chinese provinces of Shandong, Jiangsu and Zhejiang. The results indicated that entrepreneurial education and creativity have a positiv...",
