    "abstractSummaryId": "Academic achievement is a factor of interest in both psychology and education. Determining which factors have a negative or positive influence on academic performance has produced different investigations. The present study focuses on analyzing the relationship between resilience, emotional intelligence, self-concept and the academic achievement of university students. For this purpose, different self-report tools were administered to a sample of 1,020 university students from Southern Spain. The Structural Equation-based mediational analysis suggests that there is no direct relationship between resilience and...",
