    "abstractSummaryId": "High-quality teacher-child interactions in early learning environments have been regarded as a key contributor to children's early language and cognitive development in international scholarships. Little is known, however, about the longitudinal effects of children's receptive vocabularies in the Chinese context. In this study, we addressed the question of such longitudinal effects by examining the predictive effect of preschool teacher-child interaction quality on children's subsequent receptive vocabulary development in 42 kindergartens in Guangdong Province China. The results in a nested design showed that...",
