    "abstractSummaryId": "The COVID-19 pandemic led higher education institutions to transition to online learning. The present study was designed to investigate students' self-regulated learning strategies on academic performance in online learning. We analyzed the differences in college students' self-regulated learning (SRL) strategies according to their grade point average (GPA). The study included 1,163 students at a distance education university in China. Two online questionnaires were used to determine online SRL strategies. GPA scores were obtained from the university exam database to determine academic performance. The analysi...",
