    "abstractSummaryId": "This study aimed to explore the effect of parents' education anxiety on children's academic burnout, and the mediation effect of parental burnout and the moderating effect of family function. A total of 259 paired parents and children from two middle schools in central China participated in the survey. The questionnaire was conducted using the Educational Anxiety Scale, Parental Burnout Scale, Adolescent Student Burnout Inventory, and Family APGAR Index. Our results indicated that parental education anxiety had a positive predictive effect on children's academic burnout. Moreover, parental burnout played a com...",
