    "abstractSummaryId": "Objective: This study primarily examines the mechanisms through which stress affects academic burnout. Method: A total of 428 university students from three undergraduate institutions in China-Anhui Normal University, Tourism College of Zhejiang, and Bozhou University-were surveyed using the College Students' Stress Scale, the Academic Burnout Scale, the Social Support Scale, and the Self-Esteem Scale. Results: The results showed that stress significantly positively predicted academic burnout among college students and significantly negatively predicted their perceived social support. Both social support and s...",
